using ArchUnitNET.Domain;
using ArchUnitNET.Fluent;
using ArchUnitNET.Loader;
using ArchUnitNET.xUnit;
using static ArchUnitNET.Fluent.ArchRuleDefinition;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerRulesTests
{
    private static readonly Architecture Architecture = new ArchLoader().LoadAssemblies(
        typeof(Domain.Money).Assembly,
        typeof(Application.AuthorizePayment).Assembly,
        typeof(Infrastructure.HttpPaymentGateway).Assembly).Build();

    private static readonly IObjectProvider<IType> DomainLayer =
        Types().That().ResideInNamespaceMatching(@"^PaymentAuthorization\.Domain(\..*)?$").As("Domain");
    private static readonly IObjectProvider<IType> ApplicationLayer =
        Types().That().ResideInNamespaceMatching(@"^PaymentAuthorization\.Application(\..*)?$").As("Application");
    private static readonly IObjectProvider<IType> InfrastructureLayer =
        Types().That().ResideInNamespaceMatching(@"^PaymentAuthorization\.Infrastructure(\..*)?$").As("Infrastructure");

    // Technical namespaces that the business layers must not touch.
    private const string TechnicalNamespaces = @"^System\.(IO|Net|Text\.Json|Data|Diagnostics\.Process)(\..*)?$";

    [Fact]
    public void Domain_does_not_depend_on_outer_layers() =>
        Types().That().Are(DomainLayer).Should().NotDependOnAny(ApplicationLayer)
            .AndShould().NotDependOnAny(InfrastructureLayer).Check(Architecture);

    [Fact]
    public void Application_does_not_depend_on_infrastructure() =>
        Types().That().Are(ApplicationLayer).Should().NotDependOnAny(InfrastructureLayer).Check(Architecture);

    [Fact]
    public void Business_layers_do_not_use_technical_frameworks() =>
        Types().That().Are(DomainLayer).Or().Are(ApplicationLayer)
            .Should().NotDependOnAnyTypesThat().ResideInNamespaceMatching(TechnicalNamespaces)
            .Check(Architecture);
}
